import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateReport } from "../handlers/updateReport";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpaceReportEntityType } from "../types/SpaceReportEntityType";
import type { UpdateReportRequest } from "../types/UpdateReportRequest";

type Data = Awaited<ReturnType<typeof updateReport>>;
type Vars = { spacePk: SpacePartition; reportId: SpaceReportEntityType; req: UpdateReportRequest };

export function useUpdateReport(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateReport(vars.spacePk, vars.reportId, vars.req),
    ...options,
  });
}
